import{_ as t,o as i,c as a,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"ADR 0001: Repository-first documentation projected into the product site","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0001-documentation-projection.md","filePath":"decisions/0001-documentation-projection.md","lastUpdated":1788546361000}'),r={name:"decisions/0001-documentation-projection.md"};function n(s,e,d,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0001-repository-first-documentation-projected-into-the-product-site" tabindex="-1">ADR 0001: Repository-first documentation projected into the product site <a class="header-anchor" href="#adr-0001-repository-first-documentation-projected-into-the-product-site" aria-label="Permalink to &quot;ADR 0001: Repository-first documentation projected into the product site&quot;">​</a></h1><ul><li><strong>Status:</strong> Accepted; local implementation complete</li><li><strong>Date:</strong> 2026-08-27</li><li><strong>Accepted:</strong> 2026-08-28</li><li><strong>Decision owner:</strong> repository owner</li><li><strong>Related work:</strong> <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/164" target="_blank" rel="noreferrer">epic #164</a>, <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/171" target="_blank" rel="noreferrer">story #171</a></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The repository already contains extensive architecture, computation, provenance, activity-profile, operational, plan, and tracking material. The reference documents are committed to Git, but their index incorrectly called them local and gitignored. There is no declared authoring/publication contract and no browsable documentation build.</p><p>Visitors need method and evidence links beside the values they are using. A separate documentation hostname would create an unnecessary product boundary; the useful destination is the existing <code>https://panchangam.astrochaganti.com/docs/</code> site area.</p><p>The existing GitHub Pages branch cannot safely accept another independent docs publisher. Multiple workflows layer the landing site and generated calendar data into that branch, preserve each other&#39;s files, and maintain the production <code>panchangam.astrochaganti.com</code> CNAME. Documentation must therefore join the landing build atomically rather than introduce another branch writer. The workflows are frozen unless the owner explicitly approves a change.</p><h2 id="decision-drivers" tabindex="-1">Decision drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision drivers&quot;">​</a></h2><ul><li>source must be reviewable in the same pull request as code;</li><li>existing Markdown and Mermaid should remain useful on GitHub;</li><li>local full-text search and clear navigation should work without an external indexing service;</li><li>the renderer must not force framework syntax into canonical pages;</li><li>generated output must be reproducible and disposable;</li><li>public references must use stable URLs on the same origin as the feature UI;</li><li>the build path must remain isolated even though the result shares the product origin;</li><li>no new workflow may compete with existing <code>gh-pages</code> writers;</li><li>the maintenance burden should fit a small project in maintenance mode.</li></ul><h2 id="options-considered" tabindex="-1">Options considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options considered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Strengths</th><th>Costs and risks</th><th>Disposition</th></tr></thead><tbody><tr><td>GitHub-native Markdown</td><td>No added dependencies or hosting; Mermaid renders on GitHub</td><td>Weak cross-page navigation and discovery; repository search is not a documentation search experience</td><td>Keep as permanent fallback</td></tr><tr><td><a href="https://vitepress.dev/guide/what-is-vitepress" target="_blank" rel="noreferrer">VitePress</a></td><td>Small Markdown/Vite model, default docs theme, local search, and straightforward <code>/docs/</code> base/output configuration; aligns with the existing Vite build</td><td>Mermaid needs integration; the next major line is still published as an alpha, so the pilot must pin and assess the stable line</td><td>Recommended local pilot</td></tr><tr><td><a href="https://starlight.astro.build/" target="_blank" rel="noreferrer">Astro Starlight</a></td><td>Documentation-focused navigation, accessibility defaults, and built-in local <a href="https://starlight.astro.build/guides/site-search/" target="_blank" rel="noreferrer">Pagefind search</a></td><td>Adds a second application framework to the current Vite site; external-source loading and Mermaid require more integration</td><td>Pilot fallback</td></tr><tr><td><a href="https://docusaurus.io/" target="_blank" rel="noreferrer">Docusaurus</a></td><td>Mature docs platform and official Mermaid support</td><td>Larger React/MDX surface than this project needs; official search guidance favours hosted Algolia while local search is community-maintained</td><td>Do not adopt now</td></tr><tr><td><a href="https://squidfunk.github.io/mkdocs-material/" target="_blank" rel="noreferrer">Material for MkDocs</a></td><td>Excellent established docs experience, search, and diagrams</td><td>Maintainers have announced end of life for November 2026</td><td>Do not start a new site</td></tr><tr><td><a href="https://zensical.org/about/" target="_blank" rel="noreferrer">Zensical</a></td><td>Open-source successor from the Material creators with a promising migration path</td><td>Described by its own project as alpha</td><td>Monitor; reconsider after stability</td></tr><tr><td>External CMS or GitHub Wiki</td><td>Friendly browser editing</td><td>Creates a second source/repository and a drift path away from code, tests, and provenance registries</td><td>Reject as canonical source</td></tr></tbody></table><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li>Keep all canonical documentation and computation metadata in this repository under the directory contract in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/docs/README.md" target="_blank" rel="noreferrer"><code>docs/README.md</code></a>.</li><li>Keep the canonical pages renderer-neutral and usable through GitHub alone.</li><li>Use the stable VitePress line for a <strong>local, disposable projection</strong>, not as a new source format. The same Vite ecosystem and a <code>/docs/</code> build target make it the smallest fit for the clarified same-site requirement.</li><li>Use Starlight as the fallback if VitePress cannot meet accessibility, source-loading, search, or Mermaid requirements cleanly.</li><li>Publish an approved projection under <code>https://panchangam.astrochaganti.com/docs/</code> by composing <code>dist/docs/</code> into the landing build. Do not create a second documentation deployment workflow or change the production CNAME.</li><li>Map every public computation to a stable route such as <code>/docs/computations/&lt;computation-id&gt;/</code>. Feature screens should link to the method and, where safe, pass non-sensitive result context for verification.</li><li>Do not deploy or alter <code>.github/workflows/</code> in story #171. Updating the frozen landing-workflow path contract requires a later explicit owner approval after the local result is reviewed.</li></ol><h2 id="acceptance-gates" tabindex="-1">Acceptance gates <a class="header-anchor" href="#acceptance-gates" aria-label="Permalink to &quot;Acceptance gates&quot;">​</a></h2><p>The VitePress projection is acceptable only if it can:</p><ul><li>load the selected root and <code>docs/</code> Markdown without copied source files;</li><li>exclude plans, specs, tracking, and generated product data from default navigation and search;</li><li>index the reference corpus locally without a hosted search dependency;</li><li>render existing Mermaid diagrams while preserving GitHub rendering;</li><li>preserve relative links or report each required source-link change;</li><li>build deterministically into <code>dist/docs/</code> after the landing Vite build without deleting or replacing landing or generated-data artifacts;</li><li>keep <code>/docs/computations/&lt;computation-id&gt;/</code> URLs stable and validate that contextual product links resolve;</li><li>pass a keyboard, contrast, mobile, broken-link, and representative-page review; and</li><li>remain easy to remove without losing documentation source.</li></ul><p>If those gates fail, keep GitHub-native documentation and evaluate the Starlight fallback. A public site is useful, but it is not required for the documentation to remain authoritative and maintained.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Documentation can improve immediately without waiting for hosting.</li><li>Visitors stay on the current site when they move from a result to its method, evidence, and verification context.</li><li>The first projection adds a small VitePress toolchain that must be maintained and security-reviewed.</li><li>Existing historical material stays auditable but will not crowd the supported documentation experience.</li><li>The landing build becomes the atomic owner of <code>/docs/</code>; no DNS change or new <code>gh-pages</code> writer is needed.</li><li>The frozen landing-workflow path filter must eventually include canonical docs inputs so docs-only changes deploy. That change needs explicit owner approval and regression checks for every layered artifact.</li></ul><h2 id="revisit-triggers" tabindex="-1">Revisit triggers <a class="header-anchor" href="#revisit-triggers" aria-label="Permalink to &quot;Revisit triggers&quot;">​</a></h2><p>Revisit this decision if VitePress changes its stable contract, if Starlight becomes materially simpler to integrate with the existing Vite site, if the Mermaid integration becomes unmaintained, or if the documentation corpus no longer fits a static site.</p>',20)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
